/**
 * Callout tests — default and ai variant branches.
 *
 * The default variant renders with a neutral surface; the ai variant renders
 * with a brand-blue soft treatment (no AI-violet per design rule). Both always
 * render icon + optional title + body.
 */
import { render, screen } from "@testing-library/react";
import { Callout } from "../../../../src/components/wizard/primitives/Callout";

const INFO_NOTE = "This is an informational note.";
const READ_DOCS = "Read the docs.";
const NO_TITLE = "No title here.";
const DEFAULT_CALLOUT = "Default callout.";
const AI_CALLOUT = "AI callout.";

test("renders the children body text", () => {
  render(<Callout>{INFO_NOTE}</Callout>);
  expect(screen.getByText(INFO_NOTE)).toBeInTheDocument();
});

test("renders an optional title when provided", () => {
  render(<Callout title="Pro tip">{READ_DOCS}</Callout>);
  expect(screen.getByText("Pro tip")).toBeInTheDocument();
  expect(screen.getByText(READ_DOCS)).toBeInTheDocument();
});

test("omits the title element when the title prop is absent", () => {
  render(<Callout>{NO_TITLE}</Callout>);
  // No separate title div rendered — only the body.
  expect(screen.getByText(NO_TITLE)).toBeInTheDocument();
  expect(screen.queryByText("Pro tip")).not.toBeInTheDocument();
});

test("default variant renders with the neutral border class", () => {
  const { container } = render(<Callout>{DEFAULT_CALLOUT}</Callout>);
  const wrapper = container.firstChild as HTMLElement;
  // The default variant uses border-cog-border, not the blue-600 variant.
  expect(wrapper.className).toContain("border-cog-border");
});

test("ai variant renders with the blue-600 border treatment", () => {
  const { container } = render(<Callout variant="ai">{AI_CALLOUT}</Callout>);
  const wrapper = container.firstChild as HTMLElement;
  expect(wrapper.className).toContain("cog-blue-600");
});


