/**
 * Checkbox tests — checked/unchecked + onChange handler.
 *
 * The component is a role="checkbox" button that conveys state via aria-checked.
 */
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { vi } from "vitest";
import { Checkbox } from "../../../../src/components/wizard/primitives/Checkbox";

test("renders as a checkbox role with the accessible label", () => {
  render(
    <Checkbox checked={false} onChange={() => undefined} label="Enable feature" />,
  );
  expect(
    screen.getByRole("checkbox", { name: "Enable feature" }),
  ).toBeInTheDocument();
});

test("reflects checked=false as aria-checked=false", () => {
  render(
    <Checkbox checked={false} onChange={() => undefined} label="Enable feature" />,
  );
  expect(screen.getByRole("checkbox")).toHaveAttribute("aria-checked", "false");
});

test("reflects checked=true as aria-checked=true", () => {
  render(
    <Checkbox checked={true} onChange={() => undefined} label="Enable feature" />,
  );
  expect(screen.getByRole("checkbox")).toHaveAttribute("aria-checked", "true");
});

test("calls onChange with the toggled value when clicked (false → true)", async () => {
  const user = userEvent.setup();
  const onChange = vi.fn();
  render(
    <Checkbox checked={false} onChange={onChange} label="Enable feature" />,
  );
  await user.click(screen.getByRole("checkbox"));
  expect(onChange).toHaveBeenCalledWith(true);
});

test("calls onChange with the toggled value when clicked (true → false)", async () => {
  const user = userEvent.setup();
  const onChange = vi.fn();
  render(
    <Checkbox checked={true} onChange={onChange} label="Enable feature" />,
  );
  await user.click(screen.getByRole("checkbox"));
  expect(onChange).toHaveBeenCalledWith(false);
});

test("the checkbox button carries the 44px named tap rungs (WCAG 2.5.8)", () => {
  render(
    <Checkbox checked={false} onChange={() => undefined} label="Enable feature" />,
  );
  const checkbox = screen.getByRole("checkbox");
  expect(checkbox.className).toMatch(/\bmin-h-tap\b/);
  expect(checkbox.className).toMatch(/\bmin-w-tap\b/);
});

// Now backed by the shared ui `Checkbox` (design-ratchet G3c), whose drawn
// box is the design system's canonical h-cog-4 w-cog-4 (16px) rather than the
// 20px this local copy used to draw. The invariant under test is unchanged and
// still the point: the DRAWN box keeps its own small size in an aria-hidden
// span while only the interactive Root carries the 44px tap rungs.
test("the drawn checkbox box stays h-cog-4 w-cog-4 — only the hit area grows, not the visual glyph", () => {
  const { container } = render(
    <Checkbox checked={false} onChange={() => undefined} label="Enable feature" />,
  );
  const visualBox = container.querySelector('[aria-hidden="true"]');
  expect(visualBox).not.toBeNull();
  expect(visualBox?.className).toMatch(/\bh-cog-4\b/);
  expect(visualBox?.className).toMatch(/\bw-cog-4\b/);
});


