/**
 * LocationCombobox tests (#2299 plan Task 7).
 *
 * A green RTL suite does NOT prove the popover actually renders with
 * elevation in a real browser — jsdom has no layout engine, so positioning,
 * the `--radix-popover-trigger-width` measurement, and real box-shadow
 * paint are not exercised here. What IS verified: role/aria wiring, the two
 * WizardOverlay traps (Escape double-fire, Tab-trap leak), filtering,
 * free-text acceptance, disabled state, mouse-vs-blur ordering, the shared
 * hover/keyboard active index, and `useValidationFocus` wiring.
 */
import { useState } from "react";
import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";

import { LocationCombobox, type LocationComboboxProps } from "../../../../src/components/wizard/primitives/LocationCombobox";
import { useValidationFocus } from "../../../../src/hooks/useValidationFocus";

const COUNTRIES = ["Canada", "France", "Germany", "Japan"] as const;

function Harness({
  value: initialValue,
  onChange: onChangeProp,
  ...rest
}: Partial<LocationComboboxProps>): ReturnType<typeof LocationCombobox> {
  const [value, setValue] = useState(initialValue ?? "");
  return (
    <LocationCombobox
      id="loc-country"
      items={COUNTRIES}
      value={value}
      onChange={(next) => {
        setValue(next);
        onChangeProp?.(next);
      }}
      placeholder="Search countries"
      emptyMessage="No matching countries"
      label="Country"
      {...rest}
    />
  );
}

describe("LocationCombobox — role and expanded state", () => {
  it("exposes role=combobox with aria-expanded false when closed, true when open, and aria-controls pointing at the list", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    expect(combobox).toHaveAttribute("aria-expanded", "false");
    const controlsId = combobox.getAttribute("aria-controls");
    expect(controlsId).toBeTruthy();

    await user.click(combobox);

    expect(combobox).toHaveAttribute("aria-expanded", "true");
    const listbox = await screen.findByRole("listbox");
    expect(listbox.id).toBe(controlsId);
  });
});

describe("LocationCombobox — the WizardOverlay traps", () => {
  it("Escape closes the popover and does NOT bubble to an ancestor's Escape handler (no discard dialog trip)", async () => {
    // The single most valuable test in this plan: WizardOverlay is a plain
    // role="dialog" div with its own hand-rolled Escape handler that pops a
    // discard-confirm dialog. Radix portals the popover content, but React's
    // synthetic keydown still bubbles up the REACT tree — portals don't cut
    // synthetic bubbling — so an unguarded popover Escape would ALSO trip
    // that outer handler.
    const user = userEvent.setup();
    const ancestorEscapeHandler = vi.fn();

    render(
      // Stands in for WizardOverlay's dialog div + its onKeyDown.
      <div role="dialog" aria-modal="true" onKeyDown={(e) => {
        if (e.key === "Escape") ancestorEscapeHandler();
      }}>
        <Harness />
      </div>,
    );

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    expect(await screen.findByRole("listbox")).toBeInTheDocument();

    await user.keyboard("{Escape}");

    expect(combobox).toHaveAttribute("aria-expanded", "false");
    await waitFor(() => {
      expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
    });
    expect(ancestorEscapeHandler).not.toHaveBeenCalled();
  });

  it("renders no focusable descendant inside the popover list, so Tab cannot land inside it (and therefore cannot escape a hand-rolled Tab trap that only enumerates focusable elements)", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    await user.click(screen.getByRole("combobox"));
    const listbox = await screen.findByRole("listbox");

    expect(listbox).toHaveAttribute("tabindex", "-1");
    for (const option of within(listbox).getAllByRole("option")) {
      // No tabIndex attribute at all (not even 0) — selection is driven by
      // aria-activedescendant on the trigger input, never real DOM focus.
      expect(option).not.toHaveAttribute("tabindex");
    }

    // Pressing Tab leaves focus exactly where it started (the trigger) —
    // nothing inside the portaled list is in the native tab order to steal it.
    await user.keyboard("{Tab}");
    expect(document.activeElement).not.toBe(screen.getByRole("combobox"));
  });
});

describe("LocationCombobox — filtering and free text", () => {
  it("filters items as the user types", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    await user.type(combobox, "Ger");

    expect(await screen.findByRole("option", { name: "Germany" })).toBeInTheDocument();
    expect(screen.queryByRole("option", { name: "Canada" })).not.toBeInTheDocument();
  });

  it("renders Combobox.Empty when nothing matches", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    await user.type(combobox, "Zzyzx");

    expect(await screen.findByText("No matching countries")).toBeInTheDocument();
    expect(screen.queryAllByRole("option")).toHaveLength(0);
  });

  it("never renders a value not present in items as a selectable blank row", async () => {
    const user = userEvent.setup();
    render(<Harness value="Some Free Text Region" items={["Alpha", "Beta"]} />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);

    // The typed free text filters the list to nothing (no item contains it)
    // rather than injecting itself as a fake option.
    await waitFor(() => {
      expect(screen.queryAllByRole("option")).toHaveLength(0);
    });
    for (const option of screen.queryAllByRole("option")) {
      expect(option.textContent?.trim()).not.toBe("");
    }
  });

  it("accepts free text on blur/close without requiring a list selection, and does not also offer a create row for an exact match", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<Harness onChange={onChange} />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    await user.type(combobox, "Germany");

    // Exact match: exactly one option, no separate "create" affordance.
    const options = await screen.findAllByRole("option");
    expect(options).toHaveLength(1);
    expect(options[0]).toHaveTextContent("Germany");

    // The typed text is already the committed value (every keystroke fires
    // onChange) — free text needs no extra commit step.
    expect(onChange).toHaveBeenLastCalledWith("Germany");
  });
});

describe("LocationCombobox — required", () => {
  it("marks the input required and aria-required when `required` is passed", () => {
    render(<Harness required />);

    const combobox = screen.getByRole("combobox");
    expect(combobox).toBeRequired();
    expect(combobox).toHaveAttribute("aria-required", "true");
  });

  it("does not mark the input required by default", () => {
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    expect(combobox).not.toBeRequired();
  });
});

describe("LocationCombobox — Enter with a matching suggestion", () => {
  it("closes the popover on Enter when the typed value already matches exactly one suggestion, without ever pressing ArrowDown", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    await user.type(combobox, "Germany");

    // Exactly one match, never navigated with ArrowDown.
    expect(await screen.findAllByRole("option")).toHaveLength(1);
    expect(combobox).toHaveAttribute("aria-expanded", "true");

    await user.keyboard("{Enter}");

    expect(combobox).toHaveAttribute("aria-expanded", "false");
    await waitFor(() => {
      expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
    });
  });
});

describe("LocationCombobox — disabled", () => {
  it("cannot be typed into while disabled", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<Harness disabled onChange={onChange} />);

    const combobox = screen.getByRole("combobox");
    expect(combobox).toBeDisabled();

    await user.click(combobox);
    await user.type(combobox, "Germany");

    expect(onChange).not.toHaveBeenCalled();
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
  });
});

describe("LocationCombobox — mouse selection vs. blur", () => {
  it("a mouse selection wins even when a blur fires around the same interaction", async () => {
    const onChange = vi.fn();
    const user = userEvent.setup();
    render(<Harness onChange={onChange} />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    const option = await screen.findByRole("option", { name: "France" });

    // Simulate the race explicitly: fire blur immediately around the click.
    fireEvent.mouseDown(option);
    fireEvent.blur(combobox);
    await user.click(option);

    expect(onChange).toHaveBeenLastCalledWith("France");
    await waitFor(() => {
      expect(combobox).toHaveAttribute("aria-expanded", "false");
    });
  });
});

describe("LocationCombobox — shared active index", () => {
  it("hover and keyboard drive the same active index (aria-activedescendant)", async () => {
    const user = userEvent.setup();
    render(<Harness />);

    const combobox = screen.getByRole("combobox");
    await user.click(combobox);
    const canada = await screen.findByRole("option", { name: "Canada" });
    const france = screen.getByRole("option", { name: "France" });

    fireEvent.pointerMove(canada);
    await waitFor(() => {
      expect(combobox.getAttribute("aria-activedescendant")).toBe(canada.id);
    });

    await user.keyboard("{ArrowDown}");
    await waitFor(() => {
      expect(combobox.getAttribute("aria-activedescendant")).toBe(france.id);
    });
  });
});

describe("LocationCombobox — useValidationFocus wiring", () => {
  function ValidationHarness({ nonce, isInvalid }: { readonly nonce: number; readonly isInvalid: boolean }) {
    const { ref, error } = useValidationFocus<HTMLInputElement>(isInvalid, nonce);
    return (
      <LocationCombobox
        id="loc-country"
        items={COUNTRIES}
        value=""
        onChange={vi.fn()}
        placeholder="Search countries"
        emptyMessage="No matching countries"
        label="Country"
        inputRef={ref}
        ariaInvalid={error}
        describedBy="loc-country-error"
      />
    );
  }

  it("focuses the input and sets aria-invalid/aria-describedby when a nonce bump lands on an invalid field", () => {
    const { rerender } = render(<ValidationHarness nonce={0} isInvalid />);
    const combobox = screen.getByRole("combobox");
    expect(document.activeElement).not.toBe(combobox);

    rerender(<ValidationHarness nonce={1} isInvalid />);

    expect(document.activeElement).toBe(combobox);
    expect(combobox).toHaveAttribute("aria-invalid", "true");
    // `hasVisibleLabel` isn't set here, so the combobox's own sr-only
    // description id is ALSO present, space-joined ahead of the error id.
    expect(combobox.getAttribute("aria-describedby")).toContain("loc-country-error");
  });

  it("does not set aria-invalid/aria-describedby when the field is valid, even across a nonce bump", () => {
    const { rerender } = render(<ValidationHarness nonce={0} isInvalid={false} />);
    rerender(<ValidationHarness nonce={1} isInvalid={false} />);

    const combobox = screen.getByRole("combobox");
    expect(document.activeElement).toBe(combobox);
    expect(combobox).not.toHaveAttribute("aria-invalid");
    // Not invalid: the error id is never appended, even though the
    // combobox's own sr-only description id is still present.
    expect(combobox.getAttribute("aria-describedby")).not.toContain("loc-country-error");
  });
});

describe("LocationCombobox — results announcement", () => {
  it("announces the filtered count via the supplied aria-live formatter", async () => {
    const user = userEvent.setup();
    render(
      <Harness
        resultsAnnouncement={(count) => `${count} countries`}
      />,
    );

    await user.click(screen.getByRole("combobox"));
    expect(await screen.findByRole("status")).toHaveTextContent("4 countries");

    await user.type(screen.getByRole("combobox"), "Ger");
    await waitFor(() => {
      expect(screen.getByRole("status")).toHaveTextContent("1 countries");
    });
  });
});

describe("LocationCombobox — diacritic-insensitive and alias search (#2353)", () => {
  // `shouldFilter={false}` on Combobox.Root means matchesSearch is the ONLY
  // filter cmdk's own fuzzy matcher never runs — so a US/English keyboard
  // typing the ASCII spelling of an accented city/region must still find it.
  const CITIES = ["Bogotá", "München", "Côte d'Ivoire"] as const;

  it("finds an accented item when the needle is typed diacritic-free", async () => {
    const user = userEvent.setup();
    render(<Harness items={CITIES} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Bogota");

    expect(await screen.findByRole("option", { name: "Bogotá" })).toBeInTheDocument();
    expect(screen.queryByRole("option", { name: "München" })).not.toBeInTheDocument();
  });

  it("still finds the item when the needle itself carries the accent", async () => {
    const user = userEvent.setup();
    render(<Harness items={CITIES} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Bogotá");

    expect(await screen.findByRole("option", { name: "Bogotá" })).toBeInTheDocument();
  });

  it("folds both sides: an accented needle matches a plain item", async () => {
    const user = userEvent.setup();
    render(<Harness items={["Bogota", "Paris"]} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Bogotá");

    expect(await screen.findByRole("option", { name: "Bogota" })).toBeInTheDocument();
  });

  it("folds punctuation: an apostrophe-free retype matches the punctuated canonical name", async () => {
    const user = userEvent.setup();
    render(<Harness items={CITIES} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Cote d Ivoire");

    expect(await screen.findByRole("option", { name: "Côte d'Ivoire" })).toBeInTheDocument();
  });

  it("folds a hyphen the same way", async () => {
    const user = userEvent.setup();
    render(<Harness items={["Guinea-Bissau"]} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Guinea Bissau");

    expect(await screen.findByRole("option", { name: "Guinea-Bissau" })).toBeInTheDocument();
  });

  it("shows the full list unchanged for an empty needle", async () => {
    const user = userEvent.setup();
    render(<Harness items={CITIES} />);

    await user.click(screen.getByRole("combobox"));

    const listbox = await screen.findByRole("listbox");
    expect(within(listbox).getAllByRole("option")).toHaveLength(CITIES.length);
  });

  it("matches via an alias haystack while rendering only the canonical name", async () => {
    const user = userEvent.setup();
    const items = [
      { value: "München", haystacks: ["München", "Munich", "Muenchen"] },
      { value: "Paris", haystacks: ["Paris"] },
    ];
    render(<Harness items={items} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Munich");

    // The alias matched, but the rendered/selectable row is the canonical
    // display name — never the alias text.
    const options = await screen.findAllByRole("option");
    expect(options).toHaveLength(1);
    expect(options[0]).toHaveTextContent("München");
    expect(screen.queryByText("Munich")).not.toBeInTheDocument();
  });

  it("still filters correctly when items is a bare string[] (backward compat with the not-yet-updated callsite)", async () => {
    const user = userEvent.setup();
    const items: readonly string[] = ["Canada", "France", "Germany"];
    render(<Harness items={items} />);

    await user.click(screen.getByRole("combobox"));
    await user.type(screen.getByRole("combobox"), "Fra");

    expect(await screen.findByRole("option", { name: "France" })).toBeInTheDocument();
    expect(screen.queryByRole("option", { name: "Canada" })).not.toBeInTheDocument();
  });
});

describe("LocationCombobox — RTL / logical properties", () => {
  it("uses only logical inset utilities for the chevron affordance, never left/right", async () => {
    const user = userEvent.setup();
    const { container } = render(<Harness />);
    await user.click(screen.getByRole("combobox"));

    const chevron = container.querySelector("svg[aria-hidden='true']");
    expect(chevron).not.toBeNull();
    const classes = chevron?.getAttribute("class") ?? "";
    expect(classes).toMatch(/\bend-cog-3\b/);
    expect(classes).not.toMatch(/\b(start|end)-(left|right)-/);
    expect(classes).not.toMatch(/\b(pl|pr)-\d/);
    expect(classes).not.toMatch(/\bleft-\d/);
    expect(classes).not.toMatch(/\bright-\d/);
  });

  it("renders option label text with text-start, not a hardcoded text-left", async () => {
    const user = userEvent.setup();
    render(<Harness />);
    await user.click(screen.getByRole("combobox"));

    const option = await screen.findByRole("option", { name: "Canada" });
    expect(option.className).toMatch(/\btext-start\b/);
    expect(option.className).not.toMatch(/\btext-left\b/);
  });
});


