/**
 * Toggle tests — enabled switch behavior plus the optional `disabled` freeze.
 *
 * The component is a role="switch" button that conveys state via aria-checked
 * and the thumb position; `disabled` freezes it without hiding that state.
 */
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { vi } from "vitest";
import { Toggle } from "../../../../src/components/wizard/primitives/Toggle";

test("renders an enabled switch reflecting checked when no disabled prop is passed", () => {
  render(
    <Toggle checked={true} onChange={() => undefined} label="Enable feature" />,
  );
  const toggle = screen.getByRole("switch", { name: "Enable feature" });
  expect(toggle).toBeEnabled();
  expect(toggle).toHaveAttribute("aria-checked", "true");
});

test("calls onChange with the toggled value when clicked", async () => {
  const user = userEvent.setup();
  const onChange = vi.fn();
  render(
    <Toggle checked={false} onChange={onChange} label="Enable feature" />,
  );
  await user.click(screen.getByRole("switch"));
  expect(onChange).toHaveBeenCalledWith(true);
});

test("is disabled when disabled is true", () => {
  render(
    <Toggle
      checked={false}
      onChange={() => undefined}
      label="Enable feature"
      disabled={true}
    />,
  );
  expect(screen.getByRole("switch")).toBeDisabled();
});

test("does not call onChange when clicked while disabled", async () => {
  const user = userEvent.setup();
  const onChange = vi.fn();
  render(
    <Toggle
      checked={false}
      onChange={onChange}
      label="Enable feature"
      disabled={true}
    />,
  );
  await user.click(screen.getByRole("switch"));
  expect(onChange).not.toHaveBeenCalled();
});

test("still announces the frozen checked value while disabled", () => {
  render(
    <Toggle
      checked={true}
      onChange={() => undefined}
      label="Enable feature"
