  const cls = thumb!.className;

  // Under dir="rtl" the START edge is the physical right; the rtl: variants
  // negate the translate so the thumb glides toward it instead of the LTR
  // (physical right-going) direction the un-mirrored classes would produce.
  expect(cls).toContain("rtl:data-[state=unchecked]:-translate-x-cog-0-5");
  expect(cls).toContain(
