test("still announces the frozen checked value while disabled", () => {
  render(
    <Toggle
      checked={true}
      onChange={() => undefined}
      label="Enable feature"
      disabled={true}
    />,
  );
  const toggle = screen.getByRole("switch", { name: "Enable feature" });
  expect(toggle).toHaveAttribute("aria-checked", "true");
});

test("applies the shared bg/border/cursor disabled treatment, never opacity-only", () => {
  render(
    <Toggle
      checked={false}
      onChange={() => undefined}
      label="Enable feature"
      disabled={true}
    />,
  );
  const toggle = screen.getByRole("switch");
  expect(toggle).toHaveClass("disabled:cursor-not-allowed");
  expect(toggle).toHaveClass("disabled:bg-cog-surface-muted");
  expect(toggle).toHaveClass("disabled:border-cog-border");
  expect(toggle.className).not.toMatch(/disabled:opacity-/);
});

// The thumb travels the WRONG WAY under ar-AE (dir="rtl") in the pre-migration
// implementation: it always applies the same LTR-positive translate-x
// regardless of writing direction, so in RTL the checked thumb slides further
// AWAY from the physical START (right) edge instead of toward it. `Switch`
// fixes this with `rtl:` variants that flip the travel sign; mirrors the
// assertion style of ui's own Switch RTL test (frontends/ui/tests/Switch.test.tsx).
test("thumb mirrors its travel under dir=\"rtl\" so it moves toward the START edge", () => {
  render(
    <div dir="rtl">
      <Toggle checked={false} onChange={() => undefined} label="Enable feature" />
    </div>,
  );

  const toggle = screen.getByRole("switch", { name: "Enable feature" });
  const thumb = toggle.firstElementChild;
  expect(thumb).not.toBeNull();

  const cls = thumb!.className;

  // Under dir="rtl" the START edge is the physical right; the rtl: variants
  // negate the translate so the thumb glides toward it instead of the LTR
  // (physical right-going) direction the un-mirrored classes would produce.
  expect(cls).toContain("rtl:data-[state=unchecked]:-translate-x-cog-0-5");
  expect(cls).toContain(
    "rtl:data-[state=checked]:-translate-x-cog-switch-thumb-travel",
  );
});

test("uses the higher-contrast emphasized border in the off state (#2305)", () => {
  render(
    <Toggle checked={false} onChange={() => undefined} label="Enable feature" />,
  );
  const sw = screen.getByRole("switch");
  expect(sw).toHaveAttribute("data-state", "unchecked");
  // Now a ui `Switch` (Radix): the off-state border is a data-state variant on
  // the root, not a static `ring-*` on a hand-rolled button.
  expect(sw.className).toContain(
    "data-[state=unchecked]:border-cog-border-emphasized",
  );
});

// #2305 follow-up — the emphasized border above fixed track-vs-page contrast
// only. The thumb stayed `bg-white` on a near-white (`cog-surface-muted`) Off
// track, so the knob itself was invisible in light mode and the control read
// as an empty pill. design.md §10 specifies a dark thumb for light-mode Off.
test("paints the off-state thumb dark rather than white (#2305)", () => {
  render(
    <Toggle checked={false} onChange={() => undefined} label="Enable feature" />,
  );

  const sw = screen.getByRole("switch");
  expect(sw).toHaveAttribute("data-state", "unchecked");
  const thumb = sw.querySelector("span");
  expect(thumb).not.toBeNull();
  expect(thumb?.className).toContain(
    "data-[state=unchecked]:bg-cog-switch-thumb-off",
  );
  expect(thumb?.className).toContain(
    "dark:data-[state=unchecked]:bg-cog-switch-thumb-off-dark",
  );
  // An unconditional white thumb IS the #2305 bug — the colour has to be
  // state-scoped, never a bare `bg-white`.
  expect(thumb?.className).not.toMatch(/(^|\s)bg-white(\s|$)/);
});

test("keeps the on-state thumb white in light mode, inverted in dark (#2305)", () => {
  render(
    <Toggle checked={true} onChange={() => undefined} label="Enable feature" />,
  );

  const sw = screen.getByRole("switch");
  expect(sw).toHaveAttribute("data-state", "checked");
  const thumb = sw.querySelector("span");
  expect(thumb?.className).toContain("data-[state=checked]:bg-white");
  expect(thumb?.className).toContain(
    "dark:data-[state=checked]:bg-cog-switch-thumb-on-dark",
  );
});

// A disabled switch is 1.4.11-exempt, but its track is `cog-surface-muted` —
// near-white in light mode — so a white thumb would vanish there exactly the
// way the enabled Off one did. Muted, never white. Radix puts `data-disabled`
// on the Thumb itself, and the rule stacks it with the state attribute so a
// disabled switch never paints an enabled-looking thumb over a muted track.
test("uses the muted thumb while disabled, in both checked states (#2305)", () => {
  for (const checked of [false, true] as const) {
    const { unmount } = render(
      <Toggle
        checked={checked}
        onChange={() => undefined}
        label="Enable feature"
        disabled={true}
      />,
    );
    const state = checked ? "checked" : "unchecked";
    const thumb = screen.getByRole("switch").querySelector("span");
    expect(thumb?.className).toContain(
      `data-[disabled]:data-[state=${state}]:bg-cog-switch-thumb-disabled`,
    );
    unmount();
  }
});


